// Build the prompt text for each entry
function buildPrompt(entry, isServicio) {
  const char = charDescriptions[entry.character];
  const action = isServicio ? 'looking at his smartphone showing the CarMatch app with nearby service providers' : 'looking at his smartphone showing the CarMatch app with vehicle listings';
  const extra = isServicio ? 'A purple CarMatch logo is in the corner' : 'The vehicle is clean and well-presented';
  
  return `${char}, ${entry.scene}. He is ${action}. ${entry.extra || extra}. Bold white text overlay reads "${entry.overlay}" with a purple CarMatch logo in the corner. Photorealistic style, warm golden hour lighting, high contrast, professional Facebook ad photography, 1080x1080 square format.`;
}

// Generate TypeScript array entries
let output = '';

output += '\n    // === SERVICIOS (DEMANDA - 39 prompts) ===\n';
for (const s of servicios) {
  const prompt = buildPrompt(s, true);
  output += `    { id: ${s.id}, title: '${s.title}', character: '${s.character}', category: 'servicios', subcategory: '${s.subcategory}', prompt: '${prompt.replace(/'/g, "\\'")}', hook: '${s.hook.replace(/'/g, "\\'")}', cta: '${s.cta}', segmentacion: { edad: '${s.segmentacion.edad}', ubicacion: '${s.segmentacion.ubicacion}', intereses: '${s.segmentacion.intereses.replace(/'/g, "\\'")}' } },\n`;
}

output += '\n    // === COMPRADORES (DEMANDA - 97 prompts) ===\n';
for (const c of compradores) {
  const prompt = buildPrompt(c, false);
  output += `    { id: ${c.id}, title: '${c.title}', character: '${c.character}', category: 'compradores', subcategory: '${c.subcategory}', prompt: '${prompt.replace(/'/g, "\\'")}', hook: '${c.hook.replace(/'/g, "\\'")}', cta: '${c.cta}', segmentacion: { edad: '${c.segmentacion.edad}', ubicacion: '${c.segmentacion.ubicacion}', intereses: '${c.segmentacion.intereses.replace(/'/g, "\\'")}' } },\n`;
}

fs.writeFileSync('D:/CarMatchapp/carmatch-fb-ads/generated-prompts-full.txt', output);
console.log('Generated', servicios.length + compradores.length, 'full prompts');
